/**
 * Automated Node verification script for Phase 0 PDF.js PoC.
 * Reads a PDF generated by `poc/pdf-typst-poc` with `pdfjs-dist`,
 * verifies page count, viewport dimensions (A4), and extracts Japanese + math text.
 */
import fs from "node:fs";
import path from "node:path";
import * as pdfjsLib from "pdfjs-dist/legacy/build/pdf.mjs";

const defaultPdfPath = path.resolve(
  import.meta.dirname,
  "../../pdf-typst-poc/output/sample_solution.pdf",
);
const pdfPath = process.argv[2] ? path.resolve(process.argv[2]) : defaultPdfPath;

if (!fs.existsSync(pdfPath)) {
  console.error(`PDF not found: ${pdfPath}`);
  process.exit(1);
}

const data = new Uint8Array(fs.readFileSync(pdfPath));
const loadingTask = pdfjsLib.getDocument({
  data,
  useSystemFonts: true,
  disableFontFace: true,
});
const doc = await loadingTask.promise;

console.log(`PDF.js loaded: ${pdfPath}`);
console.log(`Page count: ${doc.numPages}`);

const pageSummaries = [];
for (let pageNum = 1; pageNum <= doc.numPages; pageNum++) {
  const page = await doc.getPage(pageNum);
  const vp = page.getViewport({ scale: 1.0 });
  const textContent = await page.getTextContent();
  const extracted = textContent.items
    .map((item) => ("str" in item ? item.str : ""))
    .join(" ")
    .replace(/\s+/g, " ")
    .trim();
  pageSummaries.push({
    page: pageNum,
    widthPt: Number(vp.width.toFixed(1)),
    heightPt: Number(vp.height.toFixed(1)),
    charCount: extracted.length,
    sample: extracted.slice(0, 140),
  });
}

console.log(JSON.stringify(pageSummaries, null, 2));

const allText = pageSummaries.map((p) => p.sample).join(" ");
if (doc.numPages < 1) {
  throw new Error("Expected at least 1 page");
}
if (!allText.includes("FormulaDesk") && pageSummaries.every((p) => p.charCount === 0)) {
  throw new Error("Expected extracted text from PDF");
}

console.log("PDF.js verification PASSED.");
